    .key({ laboratorioId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarLaboratorioRepository(laboratorioId, minimo) {
  const { Items = [] } = await TABLA_MUESTRAS.build(QueryCommand)
    .entities(MODELO_MUESTRA)
    .query({ index: 'PorLaboratorio', partition: laboratorioId })
    .options({ filters: { Muestra: { attr: 'cantidadMl', gte: minimo } } })
    .send();
  return Items;
}
